import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BB06nUeW.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),n={name:"09-interview-qa.md"};function i(s,e,c,d,u,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-the-architecture-of-aegisbank" tabindex="-1">Q1: Can you walk me through the architecture of AegisBank? <a class="header-anchor" href="#q1-can-you-walk-me-through-the-architecture-of-aegisbank" aria-label="Permalink to &quot;Q1: Can you walk me through the architecture of AegisBank?&quot;">​</a></h3><p><strong>Answer</strong>: AegisBank is a secure digital banking platform built on the MERN stack with Express 5, React 18, and MongoDB. The application enforces double-entry bookkeeping: every fund transfer writes paired debit and credit records into <code>ledger.model.js</code> inside an atomic MongoDB session. Our backend routes are protected by a custom JWT authentication middleware that checks an in-memory/TTL-indexed token blacklist in <code>blackList.model.js</code> to ensure immediate revocation on logout. The frontend is a clean React SPA with Axios interceptors that handles balance refreshes, payee management, and CSV statement exports.</p><h3 id="q2-what-is-double-entry-bookkeeping-and-why-did-you-use-it" tabindex="-1">Q2: What is double-entry bookkeeping and why did you use it? <a class="header-anchor" href="#q2-what-is-double-entry-bookkeeping-and-why-did-you-use-it" aria-label="Permalink to &quot;Q2: What is double-entry bookkeeping and why did you use it?&quot;">​</a></h3><p><strong>Answer</strong>: In single-entry bookkeeping, a transfer simply increments one balance and decrements another. If a database error or network partition occurs between those operations, money disappears or is created out of thin air. In double-entry bookkeeping, every financial movement consists of two equal and opposite entries: a debit to one account and an credit to another. This guarantees mathematical balance across the entire system ($Debits = Credits$) and provides an immutable audit trail for financial regulators.</p><h3 id="q3-how-do-you-prevent-race-condition-overdrafts" tabindex="-1">Q3: How do you prevent race-condition overdrafts? <a class="header-anchor" href="#q3-how-do-you-prevent-race-condition-overdrafts" aria-label="Permalink to &quot;Q3: How do you prevent race-condition overdrafts?&quot;">​</a></h3><p><strong>Answer</strong>: We use MongoDB multi-document ACID transactions with atomic session locking. When a transfer is requested, the sender&#39;s account document is read and locked within the transaction session. If a concurrent transfer attempts to withdraw from the same account, it must wait for the first transaction to complete or fail immediately with an insufficient balance error.</p><h3 id="q4-how-do-you-prevent-insecure-direct-object-references-idor" tabindex="-1">Q4: How do you prevent Insecure Direct Object References (IDOR)? <a class="header-anchor" href="#q4-how-do-you-prevent-insecure-direct-object-references-idor" aria-label="Permalink to &quot;Q4: How do you prevent Insecure Direct Object References (IDOR)?&quot;">​</a></h3><p><strong>Answer</strong>: In <code>transaction.controller.js</code> and <code>beneficiary.controller.js</code>, the code never trusts client-supplied account IDs alone. It verifies that the <code>userId</code> associated with the <code>fromAccountId</code> matches the authenticated <code>req.user._id</code> extracted from the cryptographically verified JWT token. If a malicious user attempts to transfer funds out of another customer&#39;s account number, the controller immediately rejects the request with a 403 Forbidden.</p><h3 id="q5-how-does-your-jwt-blacklist-work" tabindex="-1">Q5: How does your JWT Blacklist work? <a class="header-anchor" href="#q5-how-does-your-jwt-blacklist-work" aria-label="Permalink to &quot;Q5: How does your JWT Blacklist work?&quot;">​</a></h3><p><strong>Answer</strong>: Since JWTs are stateless, logging out normally does not invalidate the token until its expiration time. We solved this in <code>auth.controller.js</code> by writing the token to our <code>blackList</code> collection upon logout. The MongoDB schema sets a TTL index matching the token expiration, so expired tokens are automatically pruned from the database. On every authenticated request, our middleware verifies that the token does not exist in the blacklist before allowing access.</p>',12)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
